class ProviderScreen extends StatefulWidget { const ProviderScreen({super.key}); @override State<ProviderScreen> createState() => _ProviderState(); }
class _ProviderState extends State<ProviderScreen> {
  StreamSubscription<Position>? locationSub;
  final Set<String> tracked = {};
  @override void dispose() { locationSub?.cancel(); super.dispose(); }
  Future<void> track(String id) async { try { if (tracked.contains(id)) return; var p=await Geolocator.checkPermission(); if(p==LocationPermission.denied)p=await Geolocator.requestPermission(); if(p==LocationPermission.denied||p==LocationPermission.deniedForever){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('يلزم إذن الموقع باش نبعث موقع السائق.')));return;} tracked.add(id); final pos=await Geolocator.getCurrentPosition(); await FirebaseService.updateRideLocation(id,latitude:pos.latitude,longitude:pos.longitude); locationSub ??= Geolocator.getPositionStream(locationSettings:const LocationSettings(accuracy:LocationAccuracy.high,distanceFilter:15)).listen((x){for(final ride in List<String>.from(tracked)){FirebaseService.updateRideLocation(ride,latitude:x.latitude,longitude:x.longitude).catchError((_){});}}); } catch (_) { tracked.remove(id); if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ما نجّمش نفعّل التتبع توا.'))); } }
  Future<void> stop(String id) async { tracked.remove(id); if(tracked.isEmpty){await locationSub?.cancel();locationSub=null;} }
  Future<void> sendOffer(String id,double estimate) async { final c=TextEditingController(text:estimate>0?estimate.toStringAsFixed(2):''); final v=await showDialog<double>(context:context,builder:(x)=>AlertDialog(title:const Text('ابعث عرضك'),content:TextField(controller:c,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'السعر المقترح بالدينار التونسي',hintText:'اكتب عرضك')),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(x,double.tryParse(c.text.replaceAll(',','.'))),child:const Text('ابعث'))]));c.dispose();final u=FirebaseService.user;if(v==null||u==null||!v.isFinite||v<=0)return;if(v>200){final confirm=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('عرض بقيمة كبيرة'),content:Text('عرضك ${v.toStringAsFixed(2)} د.ت. ثبّت قبل الإرسال.'),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('راجع')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('أكد'))]));if(confirm!=true)return;}bool ok=false;try{ok=await FirebaseService.sendOffer(id,u.uid,v);}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ما نجّمش نبعث العرض.')));return;}if(!ok&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ما قبلناش العرض: الطلب تبدّل، أو عندك خدمة أخرى، أو تثبّت من ملفّك والتوفر.'))); }
  Future<void> advance(String id,String next) async { try{await FirebaseService.updateRide(id,next);}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ما نجّمش نبدّل حالة المشوار.')));return;} if(['arriving','arrived','active'].contains(next))await track(id); if(next=='completed')await stop(id); }
  Widget profileSettings(){
    final uid=FirebaseService.user?.uid;if(uid==null)return const SizedBox.shrink();
    return FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(future:FirebaseService.db.collection('users').doc(uid).get(),builder:(c,s){
