      final d=s.data!.data()??{}; final type=TextEditingController(text:(d['vehicleType']??'').toString());final model=TextEditingController(text:(d['vehicleModel']??'').toString());final plate=TextEditingController(text:(d['vehiclePlate']??'').toString());bool available=d['providerAvailable']==true;
      return StatefulBuilder(builder:(context,setLocal)=>Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
        Text('ملف الخدمة',style:const TextStyle(fontSize:19,fontWeight:FontWeight.w900)),
        const SizedBox(height:8),TextField(controller:type,decoration:const InputDecoration(labelText:'نوع المركبة')),TextField(controller:model,decoration:const InputDecoration(labelText:'الموديل')),TextField(controller:plate,decoration:const InputDecoration(labelText:'الترقيم')),
        SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('متوفر للطلبات'),value:available,onChanged:(v)async{try { await FirebaseService.updateProviderProfile(vehicleType:type.text,vehicleModel:model.text,plate:plate.text,available:v); if(mounted){setLocal(()=>available=v); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(v?'ولّيت متوفر للطلبات.':'وقّفت التوفر.')));} } catch (_) { if (mounted) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('ما نجّمش نبدّل التوفر. كمّل نوع المركبة والترقيم واحفظ ملف الخدمة.'))); } }}),
        SizedBox(width:double.infinity,child:FilledButton(onPressed:()async{try{await FirebaseService.updateProviderProfile(vehicleType:type.text,vehicleModel:model.text,plate:plate.text,available:available);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ملف الخدمة تحفظ.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ما نجّمش نحفظ ملف الخدمة. تثبّت من نوع المركبة والترقيم والإنترنت.')));}},child:const Text('حفظ الملف')))
      ]))));
    });
  }
  double _distanceKm(double aLat,double aLng,double bLat,double bLng){
    const r=6371.0; final dLat=(bLat-aLat)*math.pi/180; final dLng=(bLng-aLng)*math.pi/180;
    final h=math.sin(dLat/2)*math.sin(dLat/2)+math.cos(aLat*math.pi/180)*math.cos(bLat*math.pi/180)*math.sin(dLng/2)*math.sin(dLng/2);
    return 2*r*math.asin(math.sqrt(h.clamp(0.0,1.0)));
  }
  Future<void> _rateRide(String rideId) async {
    int score=5; final comment=TextEditingController();
    final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(
      title:const Text('قيّم الخدمة'), content:Column(mainAxisSize:MainAxisSize.min,children:[
        const Text('التقييم يكون على الخدمة اللي كملت، وبلا تجريح.'),
        DropdownButtonFormField<int>(value:score,decoration:const InputDecoration(labelText:'النجوم'),items:[1,2,3,4,5].map((v)=>DropdownMenuItem(value:v,child:Text('$v / 5'))).toList(),onChanged:(v){if(v!=null)setD(()=>score=v);}),
        TextField(controller:comment,maxLength:600,maxLines:3,decoration:const InputDecoration(labelText:'ملاحظة (اختيارية)')),
      ]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ابعث التقييم'))])));
    if(ok==true){try{await FirebaseService.submitRideRating(rideId:rideId,score:score,comment:comment.text);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('التقييم تسجّل.')));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('التقييم ما تسجّلش: يمكن سبق وقيّمت الخدمة.')));}} comment.dispose();
  }
  Future<void> _reportRide(String rideId) async {
    final reason=TextEditingController(); final details=TextEditingController();
    final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('شكوى على الخدمة'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:reason,maxLength:120,decoration:const InputDecoration(labelText:'سبب الشكوى')),TextField(controller:details,maxLength:1200,maxLines:3,decoration:const InputDecoration(labelText:'التفاصيل (اختيارية)'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ابعث للمالك'))]));
