  }
  Widget driverPerformance(){final uid=FirebaseService.user?.uid;if(uid==null)return const SizedBox.shrink();return FutureBuilder<Map<String,dynamic>>(future:FirebaseService.driverPerformanceSummary(uid),builder:(c,s){if(s.hasError)return const SizedBox.shrink();if(!s.hasData)return const Card(child:ListTile(leading:CircularProgressIndicator(),title:Text('نحسبوا مؤشرات الخدمة…')));final x=s.data!;final score=(x['score'] as num?)?.toDouble()??0;final rating=(x['averageRating'] as num?)?.toDouble()??0;final done=x['completedRides']??0;final cancelled=x['cancelledRides']??0;return Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('مؤشرات الخدمة',style:TextStyle(fontSize:18,fontWeight:FontWeight.w900)),const SizedBox(height:6),Row(children:[Expanded(child:Text('نقاط الخدمة: ${score.toStringAsFixed(0)}/100',style:const TextStyle(fontWeight:FontWeight.w800))),Expanded(child:Text('التقييم: ${rating==0?'ما فماش تقييمات':rating.toStringAsFixed(1)+' / 5'}'))]),const SizedBox(height:5),Text('مشاوير مكتملة: $done • ملغاة: $cancelled'),const SizedBox(height:5),const Text('الحساب يعتمد على التقييمات، نسبة الإكمال، وتوفّر بيانات تقييم موثوقة.',style:TextStyle(fontSize:12,color:Colors.black54))])));});}
  Widget available(){
    final uid=FirebaseService.user?.uid;
    if(uid==null)return const Text('يلزمك تكون داخل للحساب.');
    return StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:FirebaseService.db.collection('users').doc(uid).snapshots(),builder:(context,roleSnap){
      if(!roleSnap.hasData)return const CircularProgressIndicator();
      final profile = roleSnap.data!.data() ?? const <String, dynamic>{};
      final role=profile['role']?.toString()??'client';
      if (profile['providerVerified'] != true) return const Padding(padding:EdgeInsets.all(16),child:Text('يلزم قبول ملفّك والوثائق قبل ما توصلك طلبات الخدمة.'));
      if (profile['providerAvailable'] != true) return const Padding(padding:EdgeInsets.all(16),child:Text('فعّل «متوفر للطلبات» من ملف الخدمة باش تظهرلك الطلبات الجديدة مباشرة.'));
      return StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseService.availableRidesForRole(role),builder:(c,s){
        if(s.hasError)return const Text('ما نجّمش نجيب الطلبات المناسبة.');
        if(!s.hasData)return const CircularProgressIndicator();
        final allowed=switch(role){
          'driver'=>{'taxiMoto','carExpress','sos','ambulance','randonnee'},
          'deliveryProvider'=>{'deliveryMoto','deliveryVan','deliveryTruck'},
          'partner'=>{'taxiMoto','carExpress','deliveryMoto','deliveryVan','deliveryTruck','sos','ambulance','randonnee'},
          _=><String>{},
        };
        final docs=s.data!.docs.where((d)=>allowed.contains(d.data()['kind']?.toString())).toList();
        if(docs.isEmpty)return const Padding(padding:EdgeInsets.all(16),child:Text('ما فماش كورسات مناسبة توا. كي يجي طلب جديد، يظهر لهنا مباشرة.'));
        return FutureBuilder<Position?>(future:Geolocator.getLastKnownPosition(),builder:(ctx,posSnap){
          final pos=posSnap.data;
          double pickupDistance(QueryDocumentSnapshot<Map<String,dynamic>> d){final x=d.data();final lat=(x['pickupLat'] as num?)?.toDouble(),lng=(x['pickupLng'] as num?)?.toDouble();if(pos==null||lat==null||lng==null||!lat.isFinite||!lng.isFinite||lat.abs()>90||lng.abs()>180)return double.infinity;return _distanceKm(pos.latitude,pos.longitude,lat,lng);}
          docs.sort((a,b){final da=pickupDistance(a),db=pickupDistance(b);final byDistance=da.compareTo(db);if(byDistance!=0)return byDistance;final xa=a.data(),xb=b.data();final pa=xa['priority']=='emergency'?0:xa['priority']=='medical'?1:2;final pb=xb['priority']=='emergency'?0:xb['priority']=='medical'?1:2;if(pa!=pb)return pa.compareTo(pb);final ca=xa['createdAt'],cb=xb['createdAt'];final ta=ca is Timestamp?ca.millisecondsSinceEpoch:0,tb=cb is Timestamp?cb.millisecondsSinceEpoch:0;final byTime=tb.compareTo(ta);if(byTime!=0)return byTime;return a.id.compareTo(b.id);});
          final zones=<String,int>{}; for(final d in docs){final x=d.data();final lat=(x['pickupLat'] as num?)?.toDouble(),lng=(x['pickupLng'] as num?)?.toDouble();if(lat!=null&&lng!=null&&lat.isFinite&&lng.isFinite&&lat.abs()<=90&&lng.abs()<=180){final key='${(lat*50).round()/50}, ${(lng*50).round()/50}';zones[key]=(zones[key]??0)+1;}}
          final busy=zones.entries.where((e)=>e.value>=3).toList()..sort((a,b)=>b.value.compareTo(a.value));
          return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(pos!=null)const Padding(padding:EdgeInsets.only(bottom:6),child:Text('الطلبات مرتّبة حسب القرب؛ وعند تساوي المسافة نقدّم الاستعجالي ثم الطبي والأحدث.')),if(busy.isNotEmpty)Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('مناطق فيها طلبات أكثر توا (تقريبية)',style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:4),Text(busy.take(3).map((e)=>'${e.key} • ${e.value} طلب نشط').join('   |   '),style:const TextStyle(fontSize:12)),const SizedBox(height:4),const Text('نظهروا المنطقة كان فيها 3 طلبات نشطة على الأقل.',style:TextStyle(fontSize:11,color:Colors.black54))]))),...docs.map((d){final x=d.data();final fare=(x['estimatedFare'] as num?)?.toDouble()??0;final negotiable=x['negotiable']==true;final isAvailable=(roleSnap.data!.data()?['providerAvailable']==true);return Card(child:ListTile(contentPadding:const EdgeInsets.all(14),leading:CircleAvatar(backgroundColor:negotiable?LefTheme.cream:Colors.green.shade50,child:Icon(negotiable?Icons.route_rounded:Icons.lock_outline,color:negotiable?LefTheme.goldDark:Colors.green)),title:Text(serviceLabel(ServiceKind.values.firstWhere((k) => k.name == x['kind'], orElse: () => ServiceKind.taxiMoto)),style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Text('${x['pickup']??''} → ${x['destination']??''}\n${(x['delivery'] is Map)?'المستلِم: ${(x['delivery'] as Map)['recipientName']??''}\nالطرد: ${(x['delivery'] as Map)['parcelCategory']??''}\n':''}${negotiable?'السوم بالتفاهم • قابل للتفاوض':'السوم المحدد: ${fare.toStringAsFixed(2)} د.ت • ثابت'}'),isThreeLine:true,trailing:FilledButton(onPressed:!isAvailable?null:(negotiable?()=>sendOffer(d.id,fare):()async{try{final ok=await FirebaseService.acceptFixedRide(d.id);if(!ok&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('الكورسة ما عادش متوفرة، أو تثبّت من ملف الخدمة والتوفر.')));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ما نجّمش نقبل الكورسة توا.')));}}),child:Text(!isAvailable?'فعّل التوفر':negotiable?'قدّم عرض':'اقبل بالسعر'))));})]);
        });
      });
    });
  }
  Widget active(String uid) => StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseService.providerRides(uid),builder:(c,s){
    if(s.hasError)return const Text('المشاوير النشيطة موش متوفرة توا.'); if(!s.hasData)return const CircularProgressIndicator(); final docs=s.data!.docs.where((d){final st=(d.data()['status']??'').toString();return ['offered','countered','accepted','arriving','arrived','active','completed'].contains(st);}).toList();
    if(docs.isEmpty)return const Padding(padding:EdgeInsets.all(16),child:Text('الطلبات المقبولة باش تظهر لهنا.'));
    return Column(children:docs.map((d){final x=d.data();final st=(x['status']??'').toString();final next=switch(st){'accepted'=>'arriving','arriving'=>'arrived','arrived'=>'active','active'=>'completed',_=>null};final finalFare=(x['offerFare'] as num?)?.toDouble();final counterFare=(x['clientCounterFare'] as num?)?.toDouble();final priceText=st=='countered'&&counterFare!=null?'عرض الحريف المضاد: ${counterFare.toStringAsFixed(2)} د.ت':finalFare!=null?'${st=='offered'?'عرضك المبعوث':'السعر النهائي'}: ${finalFare.toStringAsFixed(2)} د.ت':(x['negotiable']==true?'السوم بالتفاهم':'السعر التقديري: ${((x['estimatedFare'] as num?)?.toDouble()??0).toStringAsFixed(2)} د.ت');Widget? action;
      if(st=='countered')action=FilledButton(onPressed:()async{try{final ok=await FirebaseService.acceptCounter(d.id);if(!ok&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('العرض المضاد ما عادش متوفر.')));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ما نجّمش نقبل العرض المضاد.')));}},child:const Text('اقبل العرض المضاد'));else if(next=='active'&&x['clientArrivalConfirmed']!=true)action=const FilledButton(onPressed:null,child:Text('نستناو تأكيد الحريف'));else if(next!=null)action=FilledButton(onPressed:()=>advance(d.id,next),child:Text({'arriving':'السائق جاي','arrived':'وصل','active':'المشوار بدا','completed':'كمل'}[next]??next));
      return Card(child:ListTile(title:Text('${x['pickup']??''} → ${x['destination']??''}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('الحالة: ${rideStageLabel(st)}\n$priceText'),trailing:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.end,children:[if(action!=null)action!,if(['accepted','arriving','arrived','active'].contains(st))TextButton(onPressed:()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>RideMessageMapScreen(rideId:d.id))),child:const Text('الماب والرسائل')),if(st=='completed')Wrap(children:[TextButton(onPressed:()=>_rateRide(d.id),child:const Text('قيّم الخدمة')),TextButton(onPressed:()=>_reportRide(d.id),child:const Text('شكوى'))]),if(['accepted','arriving','arrived'].contains(st))TextButton(onPressed:()async{final reason=TextEditingController();final why=await showDialog<String>(context:context,builder:(c)=>AlertDialog(title:const Text('سبب إلغاء الرحلة'),content:TextField(controller:reason,maxLength:300,maxLines:2,decoration:const InputDecoration(labelText:'السبب',hintText:'مثال: عطب في وسيلة النقل')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('رجوع')),FilledButton(onPressed:()=>Navigator.pop(c,reason.text.trim()),child:const Text('أكد الإلغاء'))]));reason.dispose();if(why==null||why.trim().length<3){if(why!=null&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('اكتب سبب واضح قبل الإلغاء.')));return;}final ok=await FirebaseService.cancelRideAsProvider(d.id,reason:why);if(ok)await stop(d.id);if(mounted&&!ok)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('الطلب هذا ما عادش ينجم يتلغى.')));},child:const Text('إلغي الطلب'))])));
    }).toList());
  });
  @override Widget build(BuildContext context){final uid=FirebaseService.user?.uid;if(uid==null)return const Scaffold(body:Center(child:Text('يلزمك تكون داخل للحساب.')));return StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:FirebaseService.db.collection('users').doc(uid).snapshots(),builder:(context,roleSnap){final role=roleSnap.data?.data()?['role']?.toString()??'driver';final delivery=role=='deliveryProvider';final title=delivery?'فضاء الديليفري':'فضاء السائق';return Scaffold(appBar:AppBar(title:Text(title,style:const TextStyle(fontWeight:FontWeight.w900))),body:ListView(padding:const EdgeInsets.all(16),children:[profileSettings(),const SizedBox(height:10),driverPerformance(),const SizedBox(height:18),Text(delivery?'طلبات الديليفري المتوفرة':'الطلبات المتوفرة',style:const TextStyle(fontSize:21,fontWeight:FontWeight.w900)),const SizedBox(height:8),available(),const SizedBox(height:26),Text(delivery?'طلبات الديليفري النشيطة':'مشاويري النشيطة',style:const TextStyle(fontSize:21,fontWeight:FontWeight.w900)),const SizedBox(height:8),active(uid)]));});}
